/**
 * @param {string} href file: URL to a .js module
 * @returns {Promise<Record<string, unknown>>}
 */
export async function loadJavascriptModule(href) {
  const mod = await import(href);
  return /** @type {Record<string, unknown>} */ (mod);
}
